import pandas as pd

# Check RFC 4180 compliance
def check_rfc4180_compliance(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    if not lines:
        return False, "Empty file"

    header = lines[0].strip()
    header_fields = header.split(',')

    for i, line in enumerate(lines[1:], start=2):
        line = line.strip()
        if not line:
            continue

        # Count fields in this line
        if line.startswith('"'):
            # Quoted field - count properly
            fields = []
            current = ''
            in_quotes = False
            for char in line:
                if char == '"':
                    in_quotes = not in_quotes
                    current += char
                elif char == ',' and not in_quotes:
                    fields.append(current.strip())
                    current = ''
                else:
                    current += char
            fields.append(current.strip())
        else:
            fields = line.split(',')

        if len(fields) != len(header_fields):
            return False, f"Line {i}: expected {len(header_fields)} fields, got {len(fields)}"

    return True, "OK"

# Check both files
for f in ['outputs/t13_city_clusters.csv', 'outputs/t13_cluster_profiles.csv']:
    ok, msg = check_rfc4180_compliance(f)
    print(f"{f}: {msg}")
