import csv
import io

def check_rfc4180_compliance(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            rows = list(reader)

        if not rows:
            return False, "Empty file"

        header = rows[0]

        for i, row in enumerate(rows[1:], start=2):
            if len(row) != len(header):
                return False, f"Line {i}: expected {len(header)} fields, got {len(row)}"

        return True, f"OK ({len(rows)} rows)"
    except Exception as e:
        return False, f"Error: {e}"

# Check both files
for f in ['outputs/t13_city_clusters.csv', 'outputs/t13_cluster_profiles.csv']:
    ok, msg = check_rfc4180_compliance(f)
    print(f"{f}: {msg}")
